// Turn the arXiv HTML rendering into plain text.
const raw = String($input.first().json.data || '');
const decode = (s) => s
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&#x27;|&apos;/g, "'")
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&#x([0-9a-f]+);/gi, (_, x) => String.fromCodePoint(parseInt(x, 16)))
  .replace(/&amp;/g, '&');

// Drop structural blocks (scripts, styles, header, footer, nav)
const html = raw.replace(/<(script|style|header|footer|nav)\b[\s\S]*?<\/\1>/gi, '');
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const title = titleMatch ? decode(titleMatch[1].trim()) : 'arXiv Paper';
const fullText = decode(html.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

return [{ json: { title, fullText } }];

const rawText = $input.first().json.output || "";

// Strip potential markdown fences
const cleaned = rawText.replace(/```json\n?|\n?```/g, "").trim();
let chapters = [];

try {
  chapters = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Failed to parse LLM outline into JSON array: " + e.message);
}

// Return each chapter as an individual n8n item
return chapters.map(ch => ({ json: ch }));

const allChapters = $("Loop Over Chapters").all();

// Join using the separator expected by the server
const fullScript = allChapters
  .map(item => item.json.output || item.json.content || "")
  .join("\n\n---\n\n");

return [{
  json: {
    text: fullScript
  }
}];

// Process items from whichever branch executed
return $input.all().map(item => {
  const data = item.json;

  // Gracefully fallback across common field names
  const title = data.title;
  const fullText = data.fullText;

  // Pull values from the INPUT node
  const inputJson = $('INPUT').first().json;
  const rawArxivID = inputJson.arxivID;
  const rawDOI = inputJson.DOI;

  let arxivID = null;
  let link = null;

  // If arxivID is present and non-empty
  if (rawArxivID && String(rawArxivID).trim() !== '') {
    const cleanArxiv = String(rawArxivID).trim();
    arxivID = `(arXiv: ${cleanArxiv})`;
    link = `https://arxiv.org/pdf/${cleanArxiv}`;
  } 
  // Fallback to DOI if arxivID is missing
  else if (rawDOI && String(rawDOI).trim() !== '') {
    arxivID = null;
    link = String(rawDOI).trim();
  }

  return {
    json: {
      title: title,
      fullText: fullText,
      arxivID: arxivID,
      link: link
    }
  };
});

const text = $input.first().json.content.parts[0].text

return [{
  json: {
    text: text
  }
}];

const text = $input.first().json.output

return [{
