// Helper function to fix/strip unpaired UTF-16 surrogate characters
function sanitizeText(str) {
  if (typeof str !== 'string') return '';
  if (typeof str.toWellFormed === 'function') {
    return str.toWellFormed();
  }
  return str.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');
}

const rawFullText = $('Paper').first().json.fullText || "";
const fullText = sanitizeText(rawFullText);

if (!fullText) {
  throw new Error("No full text found for document.");
}

// Fixed regex without empty matching alternatives
const chapterRegex = /(?=(?:^|\n)(?:Chapter|CHAPTER|Section|SECTION)\s+\d+|\n#{1,2}\s+\d+)/gi;
let rawChapters = fullText.split(chapterRegex).filter(c => c.trim().length > 300);

if (rawChapters.length <= 1) {
  const chunkSize = 8000;
  rawChapters = [];
  for (let i = 0; i < fullText.length; i += chunkSize) {
    rawChapters.push(fullText.slice(i, i + chunkSize));
  }
}

const totalDocWords = fullText.split(/\s+/).length;

const chapterMap = rawChapters.map((text, idx) => {
  const lines = text.trim().split('\n');
  const rawFirstLine = lines[0].replace(/^#+\s*/, '').trim();
  const title = sanitizeText(rawFirstLine.length < 90 ? rawFirstLine : `Section ${idx + 1}`);

  const wordCount = text.trim().split(/\s+/).length;
  const weightPercent = ((wordCount / totalDocWords) * 100).toFixed(1);

  // Sanitize sliced strings in case a slice boundary split a surrogate pair
  const excerpt = sanitizeText(text.trim().slice(0, 500).replace(/\s+/g, ' ') + "...");
  const cleanedText = sanitizeText(text.trim());

  return {
    chapter_num: idx + 1,
    title: title,
    word_count: wordCount,
    weight_percent: `${weightPercent}%`,
    excerpt: excerpt,
    text: cleanedText
  };
});

const summaryList = sanitizeText(chapterMap.map(c => 
  `Section ${c.chapter_num}: "${c.title}" | Word Count: ${c.word_count} (~${c.weight_percent} of text)\n  Excerpt: "${c.excerpt}"`
).join('\n\n'));

return [{
  json: {
    total_chapters: chapterMap.length,
    total_doc_words: totalDocWords,
    chapter_summary_list: summaryList,
    chapterMap: chapterMap
  }
}];

parameters.text:
=You are an expert curriculum designer and podcast producer.
Below is the structural breakdown of a technical document, including section titles, word counts, depth weights, and content previews.

Title: {{ $('Paper').first().json.title }}
Total Document Words: {{ $json.total_doc_words }}
Total Sections: {{ $json.total_chapters }}

Section Metadata & Focus Previews:
{{ $json.chapter_summary_list }}

Your Task:
1. Analyze where the document spends the most analytical depth based on word counts and excerpts.
2. Group sections into 2 to 5 standalone audio episodes. Ensure heavier sections (large word count/depth) get dedicated time or spans, while brief background sections are combined.
3. Define clear learning goals for each episode based on its assigned focus.

Output ONLY a valid JSON array of episode objects without markdown code fences.
Strict JSON Format:
[
  {
    "episode_num": 1,
    "episode_title": "Foundations & Core Mechanics",
    "start_chapter": 1,
    "end_chapter": 3,
    "learning_goals": "Master the initial core framework established in the opening chapters."
  }
]

