const rawLLM = $input.first().json.output || $input.first().json.content || $input.first().json.text || "";

const jsonMatch = rawLLM.match(/\[\s*\{[\s\S]*\}\s*\]/);
const cleaned = jsonMatch ? jsonMatch[0] : rawLLM.replace(/```json\n?|\n?```/g, "").trim();

let parsedData = [];
try {
  parsedData = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Failed to parse LLM JSON: " + e.message);
}

const chapterMap = $('Build Chapter Map').first().json.chapterMap || [];

return parsedData.map((ep) => {
  const matchingChapters = chapterMap.filter(
    c => c.chapter_num >= ep.start_chapter && c.chapter_num <= ep.end_chapter
  );

  const textSlice = matchingChapters.length > 0 
    ? matchingChapters.map(c => c.text).join('\n\n---\n\n')
    : $('Paper').first().json.fullText;

  return {
    json: {
      episode_num: ep.episode_num,
      episode_title: ep.episode_title,
      learning_goals: ep.learning_goals,
      lecture_text_slice: textSlice
    }
  };
});

// Flatten all chapters from all episodes into a flat, sequential task list
const allEpisodes = $input.all();
const flatQueue = [];

allEpisodes.forEach(epItem => {
  const rawLLM = epItem.json.output || epItem.json.content || epItem.json.text || "";
  const jsonMatch = rawLLM.match(/\[\s*\{[\s\S]*\}\s*\]/);
  const cleaned = jsonMatch ? jsonMatch[0] : rawLLM.replace(/```json\n?|\n?```/g, "").trim();

  let chapters = [];
  try {
    chapters = JSON.parse(cleaned);
  } catch (e) {
    chapters = [];
  }

  const parent = epItem.json;
  chapters.forEach(ch => {
    flatQueue.push({
      json: {
        episode_num: parent.episode_num,
        episode_title: parent.episode_title,
        learning_goals: parent.learning_goals,
        chapter_num: ch.chapter_num,
        title: ch.title,
        target_words: ch.target_words,
        key_topics: ch.key_topics,
        narrative_goal: ch.narrative_goal,
        lecture_text_slice: parent.lecture_text_slice
      }
    });
  });
});

return flatQueue;

const flaskResponse = $input.first().json;
const slug = flaskResponse.filename_slug || "";

// Safely pull from both items emitted by the Merge node
const mergeItems = $('Merge').all();
const textItem = mergeItems.find(i => i.json.text) || mergeItems[0] || {};
const tldrItem = mergeItems.find(i => i.json.tldr) || mergeItems[1] || {};

const fullScript = (textItem.json?.text || "").trim();
const tldrText = (tldrItem.json?.tldr || "").trim();

let title = "Untitled Episode";
let link = "";
let arxivId = "";

try {
  const paper = $('Paper').first().json;
  const inputData = $('INPUT').first().json;

  arxivId = (paper.arxiv_id || paper.arxivID || "").replace(/[^0-9.]/g, "");
  const podcastType = inputData.podcast_type || 'Podcast';
  const idLabel = arxivId ? ` (arXiv: ${arxivId})` : (paper.doi ? ` (${paper.doi})` : '');

  title = `${podcastType} - ${paper.title || 'Paper'}${idLabel}`.trim();
  link = paper.link || (arxivId ? `https://arxiv.org/abs/${arxivId}` : "");
} catch (e) {
  title = textItem.json?.title || title;
  link = textItem.json?.link || link;
}

const baseUrl = String($env.PODCAST_PUBLIC_URL || '').replace(/\/+$/, '');

return [{
  json: {
    text: fullScript,
    title: title,
    arxiv_id: arxivId,
    link: link,
    audio_url: slug ? `${baseUrl}/${slug}.mp3` : "",
    transcript_url: slug ? `${baseUrl}/${slug}.html` : "",
    tldr: tldrText,
    created_at: new Date().toISOString()
  }
}];

const allChapters = $('Lecture Series Chapter Script').all();
const episodesMap = {};

allChapters.forEach(item => {
  const d = item.json;
  const epNum = d.episode_num;

  if (!episodesMap[epNum]) {
    episodesMap[epNum] = {
      episode_num: epNum,
      episode_title: d.episode_title,
      learning_goals: d.learning_goals,
      chapters: []
    };
  }

  const chapterText = (d.output || d.text || d.content || "").trim();
  episodesMap[epNum].chapters.push(chapterText);
});

const paper = $('Paper').first().json;
const paperTitle = paper.title || "Paper";
const rawArxiv = (paper.arxiv_id || paper.arxivID || "").replace(/[^0-9.]/g, "");
const idLabel = rawArxiv ? ` (arXiv: ${rawArxiv})` : '';

return Object.values(episodesMap).map(ep => ({
  json: {
    episode_num: ep.episode_num,
    episode_title: ep.episode_title,
    title: `Lecture Series - Ep ${ep.episode_num}: ${ep.episode_title} - ${paperTitle}${idLabel}`,
    text: ep.chapters.join("\n\n---\n\n"),
    tldr: `Episode ${ep.episode_num}: ${ep.episode_title}. Focus: ${ep.learning_goals}`,
    link: paper.link || (rawArxiv ? `https://arxiv.org/abs/${rawArxiv}` : "")
  }
}));

const flaskResponse = $input.first().json || {};
const slug = flaskResponse.filename_slug || "";

// Pull current episode metadata from the active loop item
const currentEpisode = $('Loop Over Items').item.json || {};

const fullScript = (currentEpisode.text || "").trim();
const tldrText = (currentEpisode.tldr || "").trim();
const epTitle = currentEpisode.title || "Lecture Episode";
const epLink = currentEpisode.link || "";

let arxivId = "";
try {
  const paper = $('Paper').first().json;
  arxivId = (paper.arxiv_id || paper.arxivID || "").replace(/[^0-9.]/g, "");
} catch (e) {}

const baseUrl = String($env.PODCAST_PUBLIC_URL || '').replace(/\/+$/, '');

return [{
  json: {
    text: fullScript,
    title: epTitle,
    arxiv_id: arxivId,
    link: epLink,
    audio_url: slug ? `${baseUrl}/${slug}.mp3` : "",
    transcript_url: slug ? `${baseUrl}/${slug}.html` : "",
    tldr: tldrText,
    created_at: new Date().toISOString()
  }
}];
